// For std::for_each with parallel execution and index vectors
#include <algorithm>
#include <execution>
#include <numeric>
#include <vector>

#include "Halide.h"

// include common definitions (DATA_TYPE, W, H, etc)
#include "defines.hpp"

// include benchmark-specific definitions (if any)
#include "deriche.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

/*
 * Array initialization: replicate the Polybench init_array,
 * but using Halide::Buffer for the arrays.
 *
 * This version uses a small Halide pipeline, vectorized and
 * parallelized for good initialization performance.
 */
static void init_array(int w,
                       int h,
                       num_t *alpha,
                       Halide::Buffer<num_t, 2> imgIn,
                       Halide::Buffer<num_t, 2> imgOut) {
    // Silence unused parameter warnings (sizes are implied by the Buffers).
    (void)w;
    (void)h;

    // Parameter of the filter.
    *alpha = (num_t)0.25;

    // C layout: imgIn[w][h] accessed as imgIn[i][j], with j the fast dimension.
    // We store Halide buffers as (j, i) with shape (h, w) so that
    // the first dimension (j) is still the fast-varying one.
    Var i("i"), j("j");
    Func init_in("init_in"), init_out("init_out");

    // Integer expression for the polynomial initialization.
    Expr ii = cast<int32_t>(i);
    Expr jj = cast<int32_t>(j);
    Expr val_int = (313 * ii + 991 * jj) % 65536;

    // Convert to [0, 1] in num_t.
    Expr denom = cast<num_t>(Expr(65535.0f));
    init_in(j, i) = cast<num_t>(val_int) / denom;

    // imgOut is not initialized in the original C code, but we'll
    // set it to zero for completeness.
    init_out(j, i) = cast<num_t>(0);

    // Schedule: row-major over (j, i) with vectorization across j and
    // parallelism across i. This matches the memory layout and
    // maximizes throughput on large images.
    Target target = get_jit_target_from_environment();
    int vec_width = target.natural_vector_size(type_of<num_t>());
    if (vec_width < 1) vec_width = 1;

    init_in
        .reorder(j, i)       // inner loop on j (fast dimension)
        .vectorize(j, vec_width)
        .parallel(i);

    init_out
        .reorder(j, i)
        .vectorize(j, vec_width)
        .parallel(i);

    // JIT once for both Funcs.
    init_in.compile_jit(target);
    init_out.compile_jit(target);

    // Realize directly into the provided buffers.
    init_in.realize(imgIn);
    init_out.realize(imgOut);
}

int main(int argc, char *argv[]) {
    // Problem size (Polybench constants).
    int w = W;  // "width" in the original C code (outer index i)
    int h = H;  // "height" in the original C code (inner index j)

    // Allocate arrays as Halide buffers.
    //
    // Original C layout: imgIn[w][h]   -> indices imgIn[i][j],
    // with j as the fastest dimension.
    //
    // Halide layout here: Buffer(h, w) -> indices imgIn(j, i),
    // with j (first dim) as the fastest dimension.
    Halide::Buffer<num_t, 2> imgIn(h, w);
    Halide::Buffer<num_t, 2> imgOut(h, w);
    Halide::Buffer<num_t, 2> y1(h, w);
    Halide::Buffer<num_t, 2> y2(h, w);

    // Scalar parameter.
    num_t alpha;

    // Initialize input and output (imgOut gets zeroed).
    init_array(w, h, &alpha, imgIn, imgOut);

    // --------------------------------------------------------------------
    // Halide pipeline for the purely pointwise parts of the kernel:
    //   imgOut = c * (y1 + y2)
    // We use a single Func with a scalar Param "c" to handle both
    // combination steps.
    // --------------------------------------------------------------------
    Var x("x"), y("y");

    // y1 and y2 are passed into Halide as ImageParams.
    ImageParam y1_param(type_of<num_t>(), 2, "y1_param");
    ImageParam y2_param(type_of<num_t>(), 2, "y2_param");
    Param<num_t> c_param("c_param");

    Func combine("combine");
    combine(x, y) = c_param * (y1_param(x, y) + y2_param(x, y));

    // Schedule: row-major with vectorization across the fast dimension
    // (x = j) and parallelism across the slow dimension (y = i).
    Target target = get_jit_target_from_environment();
    int vec_width = target.natural_vector_size(type_of<num_t>());
    if (vec_width < 1) vec_width = 1;

    combine
        .reorder(x, y)       // inner loop over x (j / fast dim)
        .vectorize(x, vec_width)
        .parallel(y);        // parallelize across rows (i)

    // JIT-compile the small Halide pipeline in advance so we don't
    // measure compilation time.
    combine.compile_jit(target);

    // --------------------------------------------------------------------
    // Compute Deriche filter coefficients on the host (scalar math).
    // This mirrors the Polybench kernel_deriche coefficient setup.
    // --------------------------------------------------------------------
    num_t ea   = std::exp(-alpha);                 // exp(-alpha)
    num_t e2a  = std::exp(num_t(2.0) * alpha);     // exp(2*alpha)
    num_t e_2a = std::exp(num_t(-2.0) * alpha);    // exp(-2*alpha)

    num_t k = (num_t(1.0) - ea) * (num_t(1.0) - ea) /
              (num_t(1.0) + num_t(2.0) * alpha * ea - e2a);

    num_t a1 = k;
    num_t a5 = k;

    num_t a2 = k * ea * (alpha - num_t(1.0));
    num_t a6 = a2;

    num_t a3 = k * ea * (alpha + num_t(1.0));
    num_t a7 = a3;

    num_t a4 = -k * e_2a;
    num_t a8 = a4;

    num_t b1 = std::pow(num_t(2.0), -alpha);
    num_t b2 = -e_2a;

    // Coefficients used in the pointwise combinations.
    num_t c1 = (num_t)1;
    num_t c2 = (num_t)1;

    // --------------------------------------------------------------------
    // Main computational kernel: Deriche filter.
    //
    // Due to the loop-carried dependencies (IIR recurrences) along rows
    // and columns, we implement the recursive passes as explicit C++
    // loops over Halide::Buffer data, which is the recommended pattern
    // for this kind of dynamic-programming-style computation.
    //
    // We still optimize these loops for data locality and throughput by:
    //   - Using raw pointers and explicit strides instead of operator().
    //   - Parallelizing across independent rows/columns with
    //     std::execution::par_unseq.
    //
    // Buffer indexing:
    //   original C:   imgIn[i][j]
    //   Halide here:  imgIn(j, i)
    // where i in [0, w) and j in [0, h).
    // --------------------------------------------------------------------

    // Pre-compute index ranges for parallel loops.
    std::vector<int> col_indices(w);
    std::vector<int> row_indices(h);
    std::iota(col_indices.begin(), col_indices.end(), 0);
    std::iota(row_indices.begin(), row_indices.end(), 0);

    // Grab data pointers and strides once to avoid repeated virtual calls.
    num_t *imgIn_data  = imgIn.data();
    num_t *imgOut_data = imgOut.data();
    num_t *y1_data     = y1.data();
    num_t *y2_data     = y2.data();

    const ptrdiff_t imgIn_s0  = imgIn.stride(0);
    const ptrdiff_t imgIn_s1  = imgIn.stride(1);
    const ptrdiff_t imgOut_s0 = imgOut.stride(0);
    const ptrdiff_t imgOut_s1 = imgOut.stride(1);
    const ptrdiff_t y1_s0     = y1.stride(0);
    const ptrdiff_t y1_s1     = y1.stride(1);
    const ptrdiff_t y2_s0     = y2.stride(0);
    const ptrdiff_t y2_s1     = y2.stride(1);

    auto start = std::chrono::high_resolution_clock::now();

    // --------------------------------------------------------------------
    // 1) Horizontal forward recursion (left -> right).
    //
    // Original C:
    //   for (i) {
    //     ym1 = ym2 = xm1 = 0;
    //     for (j)
    //       y1[i][j] = a1*imgIn[i][j] + a2*imgIn[i][j-1] + b1*y1[i][j-1] + b2*y1[i][j-2];
    //   }
    //
    // Here we parallelize over i (columns) and keep j (rows) as the
    // inner, contiguous loop for good spatial locality.
    // --------------------------------------------------------------------
    std::for_each(std::execution::par_unseq,
                  col_indices.begin(), col_indices.end(),
                  [&](int i) {
                      num_t *col_in = imgIn_data + i * imgIn_s1;
                      num_t *col_y1 = y1_data   + i * y1_s1;

                      num_t ym1 = num_t(0);
                      num_t ym2 = num_t(0);
                      num_t xm1 = num_t(0);

                      for (int j = 0; j < h; ++j) {
                          num_t x_ij = col_in[j * imgIn_s0];
                          num_t y_ij = a1 * x_ij + a2 * xm1 + b1 * ym1 + b2 * ym2;
                          col_y1[j * y1_s0] = y_ij;

                          xm1 = x_ij;
                          ym2 = ym1;
                          ym1 = y_ij;
                      }
                  });

    // --------------------------------------------------------------------
    // 2) Horizontal backward recursion (right -> left).
    //
    // Original C:
    //   for (i) {
    //     yp1 = yp2 = xp1 = xp2 = 0;
    //     for (j = h-1; j >= 0; --j)
    //       y2[i][j] = a3*imgIn[i][j+1] + a4*imgIn[i][j+2] + b1*y2[i][j+1] + b2*y2[i][j+2];
    //   }
    //
    // Again we parallelize over i and walk j backwards along the
    // contiguous dimension.
    // --------------------------------------------------------------------
    std::for_each(std::execution::par_unseq,
                  col_indices.begin(), col_indices.end(),
                  [&](int i) {
                      num_t *col_in = imgIn_data + i * imgIn_s1;
                      num_t *col_y2 = y2_data   + i * y2_s1;

                      num_t yp1 = num_t(0);
                      num_t yp2 = num_t(0);
                      num_t xp1 = num_t(0);
                      num_t xp2 = num_t(0);

                      for (int j = h - 1; j >= 0; --j) {
                          num_t y_ij = a3 * xp1 + a4 * xp2 + b1 * yp1 + b2 * yp2;
                          col_y2[j * y2_s0] = y_ij;

                          xp2 = xp1;
                          xp1 = col_in[j * imgIn_s0];
                          yp2 = yp1;
                          yp1 = y_ij;
                      }
                  });

    // --------------------------------------------------------------------
    // 3) First pointwise combination:
    //    imgOut[i][j] = c1 * (y1[i][j] + y2[i][j]);
    //
    // Implemented as a Halide Func, scheduled to be vectorized and
    // parallelized across rows.
    // --------------------------------------------------------------------
    y1_param.set(y1);
    y2_param.set(y2);
    c_param.set(c1);
    combine.realize(imgOut);

    // --------------------------------------------------------------------
    // 4) Vertical forward recursion (top -> bottom).
    //
    // Original C:
    //   for (j) {
    //     tm1 = ym1 = ym2 = 0;
    //     for (i)
    //       y1[i][j] = a5*imgOut[i][j] + a6*imgOut[i-1][j] + b1*y1[i-1][j] + b2*y1[i-2][j];
    //   }
    //
    // In our (j, i) layout, this becomes outer loop over j (rows),
    // inner over i (columns), with recurrence along the i dimension.
    // Each j-row is independent, so we parallelize over j.
    // --------------------------------------------------------------------
    std::for_each(std::execution::par_unseq,
                  row_indices.begin(), row_indices.end(),
                  [&](int j) {
                      // Starting pointers for row j (x = j, y = 0).
                      num_t *row_out = imgOut_data + j * imgOut_s0;
                      num_t *row_y1  = y1_data     + j * y1_s0;

                      num_t tm1 = num_t(0);
                      num_t ym1 = num_t(0);
                      num_t ym2 = num_t(0);

                      for (int i = 0; i < w; ++i) {
                          num_t x_ij = row_out[i * imgOut_s1];
                          num_t y_ij = a5 * x_ij + a6 * tm1 + b1 * ym1 + b2 * ym2;
                          row_y1[i * y1_s1] = y_ij;

                          tm1 = x_ij;
                          ym2 = ym1;
                          ym1 = y_ij;
                      }
                  });

    // --------------------------------------------------------------------
    // 5) Vertical backward recursion (bottom -> top).
    //
    // Original C:
    //   for (j) {
    //     tp1 = tp2 = yp1 = yp2 = 0;
    //     for (i = w-1; i >= 0; --i)
    //       y2[i][j] = a7*imgOut[i+1][j] + a8*imgOut[i+2][j] + b1*y2[i+1][j] + b2*y2[i+2][j];
    //   }
    //
    // Again we parallelize over j and walk i backwards along the
    // column direction for that row.
    // --------------------------------------------------------------------
    std::for_each(std::execution::par_unseq,
                  row_indices.begin(), row_indices.end(),
